using GH_Net.Core.Enums;using GH_Net.Licensing;using GH_Net.Service.Abstractions;using GH_Net.WPF.Localization;using GH_Net.WPF.ViewModels;using GH_Net.WPF.Views;using System.ComponentModel;using System.Windows;
namespace GH_Net.WPF;
public partial class MainWindow:Window
{private readonly JobsViewModel _jobs;private readonly IScannerConfigService _scannerConfig;private readonly IZebraPrinterConfigService _printerConfig;private readonly IJobRuntimeCoordinator _runtime;private readonly ShellViewModel _shell;private readonly LanguageService _language;private readonly ILicenseManager _license;private PackingMainViewModel? _current;private int? _jobId;public MainWindow(JobsViewModel jobs,IScannerConfigService scannerConfig,IZebraPrinterConfigService printerConfig,IJobRuntimeCoordinator runtime,ShellViewModel shell,ILicenseManager license,LanguageService language){InitializeComponent();_jobs=jobs;_scannerConfig=scannerConfig;_printerConfig=printerConfig;_runtime=runtime;_shell=shell;_license=license;_language=language;DataContext=shell;_jobs.RequestCreateJob=OpenCreate;_jobs.RequestOpenJob=OpenJob;MainContent.Content=new JobsView{DataContext=_jobs};Loaded+=OnLoaded;Closing+=OnClosing;Closed+=(_,_)=>_shell.Dispose();}
private async void OnLoaded(object s,RoutedEventArgs e){await _jobs.LoadAsync();await RestoreDevices();}private async Task RestoreDevices(){if(_license.HasFeature(LicenseFeature.Scanner))try{await _scannerConfig.ConnectSavedAsync();}catch{}if(_license.HasFeature(LicenseFeature.Printer))try{await _printerConfig.ConnectSavedAsync();}catch{}_shell.RefreshDeviceStatus();}
private async void OpenCreate(){var vm=App.GetService<CreateJobViewModel>();var d=new CreateJobWindow(vm){Owner=this};if(d.ShowDialog()==true){await _jobs.LoadAsync();if(vm.CreatedJob is not null)_jobs.SelectJob(vm.CreatedJob.Id);}}
private async void OpenJob(int id){_current?.Dispose();var vm=App.GetService<PackingMainViewModel>();_current=vm;_jobId=id;vm.RequestBack=ShowJobs;vm.RequestTrace=OpenTrace;vm.RequestExport=OpenExport;MainContent.Content=new PackingMainView{DataContext=vm};await vm.LoadAsync(id);}
private void OpenTrace()=>new TraceabilityWindow(App.GetService<TraceabilityViewModel>()){Owner=this}.ShowDialog();private async void OpenExport(int id){var vm=App.GetService<PackingExportViewModel>();await vm.LoadAsync(id);new PackingExportWindow(vm){Owner=this}.ShowDialog();}
private async void OpenSettings(){if(_runtime.CurrentStatus==JobStatus.Running){AppMessageWindow.Show(this,_language.Get("Main.SettingsBlocked"),_language.Get("Main.SettingsBlockedTitle"),AppMessageKind.Warning);return;}new SettingsWindow(App.GetService<SettingsViewModel>()){Owner=this}.ShowDialog();_shell.RefreshDeviceStatus();}
private async void ShowJobs(){_current?.Dispose();_current=null;_jobId=null;await _runtime.ReleaseJobAsync();MainContent.Content=new JobsView{DataContext=_jobs};await _jobs.LoadAsync();}
private void Settings_Click(object s,RoutedEventArgs e)=>OpenSettings();private async void License_Click(object s,RoutedEventArgs e){new LicenseWindow(App.GetService<LicenseViewModel>(),false){Owner=this}.ShowDialog();if(_license.Current.IsValid)await RestoreDevices();}
private void OnClosing(object? s,CancelEventArgs e){if(_runtime.CurrentStatus!=JobStatus.Running)return;e.Cancel=true;AppMessageWindow.Show(this,_language.Get("Main.CloseBlocked"),_language.Get("Main.CloseBlockedTitle"),AppMessageKind.Warning);}private void About_Click(object s,RoutedEventArgs e)=>AppMessageWindow.Show(this,_language.Get("Main.About"),_language.Get("Main.AboutTitle"),AppMessageKind.Information);}
